// Working line (turnStatusRows ruling): the 3.6556.2 loading line U6 (c96d752d0) in its gate-on branch, generated by
// scripts/extract-working-line.mjs, fed by src/working-line-model.mjs and mounted by src/source-working-line.jsx.
// SSR in middleware mode only (hmr / ws off); no browser, Electron or engine.
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';
import { extractWorkingLine, workingLineManifestFor, runSlicer, WORKING_LINE } from '../scripts/extract-working-line.mjs';

const app = path.resolve(import.meta.dirname, '..');
const dir = path.join(app, 'src/generated/working-line');
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
const reference = path.resolve(app, '../reference', manifest.referenceSnapshot, 'ion-dist/assets/v1');
const viewTabs = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/view-tabs/manifest.json'), 'utf8'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const occurrences = (text, needle) => text.split(needle).length - 1;

let server, Line, Model, Status, Rows, Adapters, Morph;
before(async () => {
  // D21: view-tabs' preload-helper calls document.createElement while its module evaluates.
  globalThis.document ??= { createElement: () => ({ relList: { supports: () => false } }), querySelector: () => null, head: { appendChild() {} } };
  // The import chain reaches view-tabs' shared-4 (source-menu.jsx imports the view-tabs facade), which reads
  // document.documentElement.getAttribute while its module evaluates.
  globalThis.document.documentElement ??= { getAttribute: () => null, setAttribute() {}, removeAttribute() {}, classList: { add() {}, remove() {}, contains: () => false }, style: {} };
  server = await createServer({ configFile: false, root: app, plugins: [react()], server: { middlewareMode: true, hmr: false, ws: false, watch: null },
    appType: 'custom', logLevel: 'error' });
  Line = await server.ssrLoadModule('/src/source-working-line.jsx');
  Model = await server.ssrLoadModule('/src/working-line-model.mjs');
  Status = await server.ssrLoadModule('/src/transcript-status-model.mjs');
  Rows = await server.ssrLoadModule('/src/generated/working-line/turn-status-rows.mjs');
  Adapters = await server.ssrLoadModule('/src/source-working-line-adapters.jsx');
  ({ Morph } = await server.ssrLoadModule('/src/generated/working-line/morph.mjs'));
});
after(() => server?.close());

const ready = { sessionKey: 'a', ready: true, connected: true };
const view = state => Status.transcriptStatusPresentation({ ...ready, ...state });
const render = (state, extra = {}, thinkingToggle = null) =>
  renderToStaticMarkup(React.createElement(Line.SourceWorkingLine, { line: Model.workingLineProps(view(state), extra), thinkingToggle }));
const CLOCK = s => `<span aria-hidden="true" class="shrink-0 text-muted tabular-nums">${s}</span>`;
const DOT = '<span aria-hidden="true" class="shrink-0 text-muted tabular-nums select-none">·</span>';
const TRAILING = '<span class="epitaxy-status-control inline-flex min-w-0 items-center gap-xs">';
const header = m => `// Original Claude Desktop 3.6556.2 bindings from ${m.source}; generated by extract-working-line.mjs.\n`;

test('generator --check: the output matches the 3.6556.2 originals', async () => {
  const checked = await extractWorkingLine({ check: true });
  assert.equal(checked.referenceVersion, '3.6556.2');
  assert.equal(checked.referenceSnapshot, 'snapshots/claude-3.6556.2-20261025-192807');
  assert.ok(fs.existsSync(path.join(app, 'scripts/verify-gen-working-line.mjs')));
  assert.match(fs.readFileSync(path.join(app, 'scripts/verify-gen-working-line.mjs'), 'utf8'), /extractWorkingLine\(\{ check: true \}\)/);
  // R1: the generator takes its version, snapshot and React aliases from official-3.6556.2.mjs.
  assert.match(fs.readFileSync(path.join(app, 'scripts/extract-working-line.mjs'), 'utf8'), /import \* as v3 from '\.\/official-3\.6556\.2\.mjs';/);
});

test('manifest: every module hashes to its reference chunk and output; roots carry their original text', () => {
  assert.equal(manifest.gate.flag, '__gb__2846116625');
  for (const m of manifest.modules) {
    const text = fs.readFileSync(path.join(dir, m.target), 'utf8');
    assert.equal(sha(text), m.sha256, m.target);
    assert.equal(m.referenceVersion, '3.6556.2', m.target);
    if (m.legacyShim) continue;
    assert.equal(sha(fs.readFileSync(path.join(reference, m.source))), m.sourceSha256, m.source);
    if (!m.verbatim) assert.ok(text.startsWith(header(m)), m.target);
  }
  assert.deepEqual(fs.readdirSync(dir, { recursive: true }).filter(name => name !== 'public-assets').sort(),
    [...manifest.modules.map(m => m.target), ...manifest.publicAssets.map(a => `public-assets/${a.name}`), 'manifest.json'].sort());
  // The clay mark's sheets the original names by /assets/v1 URL: checked copies of the snapshot's files.
  assert.equal(manifest.publicAssets.length, 6);
  for (const asset of manifest.publicAssets) assert.equal(sha(fs.readFileSync(path.join(dir, 'public-assets', asset.name))), sha(fs.readFileSync(path.join(reference, asset.name))), asset.name);
  // T4: the classic / sprite marks and the clay mark's gate are gone with their chunks (c98f11b7a, cca15fd43, shared-4 Ny).
  for (const gone of ['activity-marks.mjs', 'c98f11b7a-DyaVNKTh.js', 'cca15fd43-C_oOPIWW.js']) assert.ok(!fs.existsSync(path.join(dir, gone)), gone);
  // Root entry feature checks on the generated text (a reused minified name would bind another value).
  const line = fs.readFileSync(path.join(dir, 'working-line.mjs'), 'utf8');
  for (const feature of ['Get = "code-working-line"', '"data-testid": Get,', 'U6 as WorkingLine', 'toolLabelEndedAt: b,', 'b !== void 0 ? b + 2e3 : void 0',
    'defaultMessage: "1 token"', 'defaultMessage: "{tokens} tokens"', 'F6 = "\\u00B7"', 'jT as activityMark', 'mark: "clay"'])
    assert.ok(line.includes(feature), feature);
  assert.ok(!line.includes('__gb__507049721'));
  assert.match(line, /import \{[^}]*\buseTurnStatusRows as Pv\b[^}]*\} from "\.\/turn-status-rows\.mjs";/);
  // E3 / R3: the compiled closure takes its memo cache helpers from view-tabs' semantic names.
  assert.match(line, /import \{[^}]*\breactMemoCache as J9\b[^}]*\} from "\.\.\/view-tabs\/shared-frame-6jtSkIit\.js";/);
  const rows = fs.readFileSync(path.join(dir, 'turn-status-rows.mjs'), 'utf8');
  for (const feature of ['qe = "__gb__2846116625"', 'return l(D) ?? !1;', 'value: a, children: t']) assert.ok(rows.includes(feature), feature);
  const status = fs.readFileSync(path.join(dir, 'turn-status.mjs'), 'utf8');
  for (const feature of ['"data-cds": "TurnStatus",', '"data-cds": "TurnStatusStep",', 'It = Object.assign(Ft, { Step: Et, Phrases: dt })']) assert.ok(status.includes(feature), feature);
  // T2: the no-response retry labels (c4a9ee384 ym / xm).
  const errors = fs.readFileSync(path.join(dir, 'api-errors.mjs'), 'utf8');
  for (const feature of ['defaultMessage: "No response from the API"', 'defaultMessage: "The API didn\\u2019t respond to {host}"',
    'defaultMessage: "Trying once more, for up to {minutes} min"', 'ym as apiRetryLabel', 'xm as apiRetryCountText'])
    assert.ok(errors.includes(feature), feature);
  const motion = manifest.modules.find(m => m.target === 'vendor-motion.mjs');
  assert.equal(motion.source, 'vendor-motion-DlXQpU4V.js');
  // The Spark's sprites: the lazy import resolves to the chunk emitted under its own name.
  assert.ok(fs.readFileSync(path.join(dir, 'shared-frame.mjs'), 'utf8').includes('import("./cf2613ee5-Btwr9m9F.js")'));
  assert.match(fs.readFileSync(path.join(dir, 'cf2613ee5-Btwr9m9F.js'), 'utf8'), /export \{ e as animations \};/);
});

test('the reference still carries the pinned strings exactly where the extractor found them', () => {
  const read = name => fs.readFileSync(path.join(reference, name), 'utf8');
  assert.equal(occurrences(read('c96d752d0-CWv_7-n9.js'), '"code-working-line"'), 1);
  assert.equal(occurrences(read('c26fb8b6b-B7Friu61.js'), '__gb__2846116625'), 1);
  assert.equal(occurrences(read('c734f318c-SHcb2X2p.js'), '"data-cds":"TurnStatusStep"'), 2);
  assert.equal(occurrences(read('c734f318c-SHcb2X2p.js'), '"data-cds":"TurnStatus"'), 1);
  assert.equal(occurrences(read('c4a9ee384-RLCjceOL.js'), '"No response from the API"'), 1);
  // E14: no chunk of 3.6556.2 reads the clay mark's gate any more.
  for (const name of fs.readdirSync(reference).filter(n => n.endsWith('.js'))) assert.ok(!read(name).includes('__gb__507049721'), name);
});

test('generated modules import only siblings, React, the adapter module and view-tabs semantic names (D1)', () => {
  const allowed = new Set(['react', 'react-dom', 'react/jsx-runtime', 'react/compiler-runtime', '../../source-working-line-adapters.jsx']);
  const publicByFile = new Map();
  for (const [name, { file }] of Object.entries(viewTabs.publicNames)) publicByFile.set(file, [...(publicByFile.get(file) ?? []), name]);
  for (const m of manifest.modules) {
    const text = fs.readFileSync(path.join(dir, m.target), 'utf8');
    for (const [, names, from] of text.matchAll(/^(?:import|export) \{([^}]*)\} from "([^"]+)";$/gm)) {
      if (from.startsWith('./')) assert.ok(manifest.modules.some(x => `./${x.target}` === from), `${m.target} -> ${from}`);
      else if (from.startsWith('../view-tabs/')) {
        const file = from.slice('../view-tabs/'.length);
        for (const spec of names.split(',').map(s => s.trim()).filter(Boolean))
          assert.ok(publicByFile.get(file)?.includes(spec.split(/\s+as\s+/)[0]), `${m.target} imports ${spec} from ${file}`);
      } else assert.ok(allowed.has(from), `${m.target} -> ${from}`);
    }
  }
  // Module state copied next to view-tabs is the documented, harmless set only.
  const shared = manifest.modules.find(m => m.target === 'shared-frame.mjs');
  for (const name of ['hi', 'Th', 'kf']) assert.ok(shared.heldByViewTabs.includes(name), name);
});

// E34 / wave 7: transcript-rows (2.42304.0 until wave 6), src/source-transcript-status.jsx and the MCP card adapters
// import this area. Every such import must resolve to a semantic name or this version's own shared name; the 2.42304.0
// legacy names (legacyExports, legacy shim files) were removed in wave 7 once no importer was left.
test('consumer imports: every consumer import of this area resolves to a semantic or shared name, none to a legacy name', () => {
  const { parseAst } = createRequire(path.join(app, 'package.json'))('rolldown/parseAst');
  const files = [];
  const walk = d => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name);
    if (e.isDirectory()) { if (p !== dir) walk(p); } else if (/\.(m?js|jsx)$/.test(e.name)) files.push(p); } };
  walk(path.join(app, 'src'));
  const imported = new Map();
  for (const file of files) {
    const code = fs.readFileSync(file, 'utf8');
    if (!code.includes('working-line/')) continue;
    for (const node of parseAst(code, { lang: file.endsWith('jsx') ? 'jsx' : 'js' }).body) {
      if (!node.source || !['ImportDeclaration', 'ExportNamedDeclaration'].includes(node.type)) continue;
      const target = path.resolve(path.dirname(file), node.source.value);
      if (path.dirname(target) !== dir) continue;
      for (const s of node.specifiers ?? []) {
        const name = node.type === 'ImportDeclaration' ? s.imported.name : s.local.name;
        if (!imported.has(path.basename(target))) imported.set(path.basename(target), new Set());
        imported.get(path.basename(target)).add(name);
      }
    }
  }
  assert.ok(imported.size >= 9, 'consumers found');
  for (const [target, names] of imported) {
    const m = manifest.modules.find(x => x.target === target);
    assert.ok(m, target);
    assert.ok(!m.legacyShim && !m.legacyExports, `${target}: no legacy shim or legacy names (wave 7)`);
    const exported = new Set([...Object.values(m.exports), ...m.sharedExports]);
    for (const name of names) assert.ok(exported.has(name), `${target} exports ${name}`);
  }
  assert.ok(manifest.modules.every(m => !m.legacyShim && !m.legacyExports), 'no legacy shim modules or legacy names left');
  // Review fix (w6-transcript-rows-cont): transcript-rows never imports an E34 legacy name. Every import it makes from
  // this area without a semantic name is a `linkExports` entry (this version's own local, recorded in the manifest), so
  // removing the legacy shims in wave 7 leaves it resolving. A legacy name that is also the binding's own local (C, tn)
  // is the same export either way.
  const rowsDir = path.join(app, 'src/generated/transcript-rows');
  let rowImports = 0;
  for (const file of fs.readdirSync(rowsDir).filter(f => /\.m?js$/.test(f))) {
    const code = fs.readFileSync(path.join(rowsDir, file), 'utf8');
    if (!code.includes('../working-line/')) continue;
    for (const node of parseAst(code).body) {
      if (node.type !== 'ImportDeclaration' || !node.source.value.startsWith('../working-line/')) continue;
      const m = manifest.modules.find(x => x.target === node.source.value.slice('../working-line/'.length));
      assert.ok(m && !m.legacyShim, `${file} -> ${node.source.value}`);
      const own = new Set(m.bindings.map(b => b.name));
      for (const s of node.specifiers) {
        rowImports++;
        const name = s.imported.name;
        if (Object.values(m.exports).includes(name)) continue;
        assert.ok(m.linkExports?.includes(name) && own.has(name), `${file} imports ${m.target} ${name}: not a linkExports binding of this version`);
        const legacy = m.legacyExports?.[name];
        assert.ok(!legacy || legacy === `${m.source}#${name}`, `${file} imports ${m.target} ${name}, an E34 legacy name for ${legacy}`);
      }
    }
  }
  assert.ok(rowImports >= 40, 'transcript-rows imports found');
  // A linkExports entry is exported under its own name.
  for (const m of manifest.modules) for (const local of m.linkExports ?? []) {
    assert.ok(m.bindings.some(b => b.name === local), `${m.target} linkExports ${local} is sliced here`);
    assert.ok(m.sharedExports.includes(local) || Object.hasOwn(m.exports, local), `${m.target} exports ${local}`);
  }
  // A few bindings the module map placed wrongly are pinned to the right ones by their own text.
  const morph = fs.readFileSync(path.join(dir, 'morph.mjs'), 'utf8');
  // So (2.42304.0 Ja, the host's turn-mark reader) is published under its semantic name; Ba is a linkExport.
  assert.match(morph, /\bSo as useTurnMarkHeld,/); assert.match(morph, /^\s*Ba,$/m); assert.doesNotMatch(morph, /\b(?:Ba as Ca|So as Ja),/);
  const frame = fs.readFileSync(path.join(dir, 'shared-frame.mjs'), 'utf8');
  // Mh (turn-mark's reduced-motion hook, 2.42304.0 Nm) reads the html reduce-motion attribute, not ni (cds_mobile_sheets
  // loaded); transcript-rows imports it as a linkExport.
  assert.match(frame, /^\s*Mh,$/m); assert.doesNotMatch(frame, /\b(?:Mh as Nm|wn as Z)\b/);
  assert.match(frame, /function Mh\(\) \{\s*return \w+\(kh, Ah, jh\);/); // w12-viewtabs (D1): Ch (shared-frame "data-reduce-motion") is view-tabs reduceMotionAttribute, imported, not sliced.
  assert.match(frame, /\breduceMotionAttribute as Ch,/); assert.doesNotMatch(frame, /Ch = "data-reduce-motion"/);
});

// w10-cleanup-slicer-d1: runSlicer has no 2.42304.0 defaults and no E34 options left; both callers pass 3.6556.2.
test('runSlicer: the snapshot is required, the E34 legacy options are gone', async () => {
  for (const key of ['referenceVersion', 'referenceSnapshot', 'source', 'vendor']) {
    const { [key]: _drop, ...cfg } = WORKING_LINE;
    await assert.rejects(runSlicer(cfg, { dryRun: true }), new RegExp(`${key} is required`), key);
  }
  for (const key of ['legacyExports', 'legacyView'])
    await assert.rejects(runSlicer({ ...WORKING_LINE, [key]: {} }, { dryRun: true }), new RegExp(`${key} was removed in wave 10`), key);
  const text = fs.readFileSync(path.join(app, 'scripts/extract-working-line.mjs'), 'utf8');
  for (const gone of ['const legacy =', 'frozenLinkedView', 'legacyOut', 'manifest.legacy =', 'vendor-frame-DfPJ1QmD.js'])
    assert.ok(!text.includes(gone), gone);
  const rows = fs.readFileSync(path.join(app, 'scripts/extract-transcript-rows.mjs'), 'utf8');
  assert.match(rows, /referenceVersion: v3\.referenceVersion, referenceSnapshot: v3\.referenceSnapshot, source: v3\.ionSource, vendor: \{ \[v3\.vendorFrame\]: v3\.reactAliases \}/);
  assert.equal(WORKING_LINE.referenceVersion, '3.6556.2');
});

test('no legacy segment (wave 7): no consumer of this area is left on 2.42304.0', () => {
  assert.equal(manifest.legacy, undefined);
  assert.equal(fs.existsSync(path.join(app, 'scripts/working-line-legacy-2.42304.0.json')), false);
  assert.equal(workingLineManifestFor(manifest, '3.6556.2'), manifest);
  assert.throws(() => workingLineManifestFor(manifest, '2.42304.0'), /working-line is 3\.6556\.2, expected 2\.42304\.0/);
  assert.throws(() => workingLineManifestFor(manifest, '1.0.0'), /working-line is 3\.6556\.2, expected 1\.0\.0/);
});

test('gate wiring: the host GrowthBook serves turnStatusRows; Je (TurnStatusRowsProvider) provides it to the line', () => {
  assert.equal(Line.WORKING_LINE_TURN_STATUS_ROWS, true);
  assert.equal(Rows.TURN_STATUS_ROWS_FLAG, '__gb__2846116625');
  const Probe = () => String(Rows.useTurnStatusRows());
  assert.equal(renderToStaticMarkup(React.createElement(Probe)), 'false', 'no provider: Xe() ?? false');
  assert.equal(renderToStaticMarkup(React.createElement(Rows.TurnStatusRowsOverride, { value: true }, React.createElement(Probe))), 'true');
  // Je (the GrowthBook provider) answers the host's GrowthBook: on for turnStatusRows, off for everything else.
  assert.equal(renderToStaticMarkup(React.createElement(Rows.TurnStatusRowsProvider, null, React.createElement(Probe))), 'true');
  assert.equal(Adapters.useGrowthBookFlag('__gb__2846116625'), true);
  // E14: the clay mark's gate is gone from 3.6556.2 and from the host table.
  assert.equal(Adapters.useGrowthBookFlag('__gb__507049721'), false);
  for (const flag of ['ccr_thinking_token_count', '__gb__1616707004', '__gb__2346508742']) assert.equal(Adapters.useGrowthBookFlag(flag), false, flag);
  assert.equal(Adapters.useGrowthBookFlagWhen('__gb__2846116625', true), true);
  assert.equal(Adapters.useGrowthBookFlagWhen('__gb__2846116625', false), false);
  const source = fs.readFileSync(path.join(app, 'src/source-working-line.jsx'), 'utf8');
  assert.match(source, /<TurnStatusRowsProvider>\s*<WorkingLine \{\.\.\.line\} \/>/);
  // The transcript status mounts it; main.jsx keeps passing the same props (no new wiring there).
  assert.match(fs.readFileSync(path.join(app, 'src/source-transcript-status.jsx'), 'utf8'), /<SourceWorkingLine line=\{line\} textSize=\{textSize\} \/>/);
  // Readers of the gate outside this area have not been migrated yet (see the report's follow-ups).
  assert.match(fs.readFileSync(path.join(app, 'src/source-transcript-states.jsx'), 'utf8'), /__gb__2846116625 gate \(cfc63964b b\(\), default false\)/);
});

test('busy: Spark mark, clock and tokens separated by the middle dot (3s · 21 tokens, 57s · 1.1k tokens)', () => {
  const html = render({ running: true }, { elapsed: 3, outputTokens: 21, waiting: 'model' });
  assert.match(html, /^<div data-testid="code-working-line" data-turn-working="true" class="flex min-h-control flex-col"><div data-closed="" data-cds="TurnStatus" data-state="busy"/);
  assert.match(html, /<span aria-hidden="true" data-cds-row-mark="" class="relative flex h-\[1lh\] shrink-0 items-center justify-center w-\[20px\] me-\[calc\(12px_-_var\(--cds-gap-xs\)\)\]">/);
  // The original CDS Spark (before its sprite strip loads), at 100% of the size-icon box. The clay mark (c05970c42 s →
  // cc39db724, "WorkingMark", ungated since 3.6556.2) leads; the Spark underneath fades out.
  assert.match(html, /opacity-0 transition-opacity delay-150 duration-200 ease-out"><svg data-cds="Spark"/);
  assert.match(html, /<span data-testid="TurnStatusClayMark" aria-hidden="true" data-cds="WorkingMark" class="relative block shrink-0 select-none" style="width:20px;height:20px;color:var\(--cds-clay\)">/);
  assert.ok(html.includes(`${CLOCK('3s')}</span>${DOT}`), 'clock then the dot');
  assert.ok(html.includes(`${TRAILING}21 tokens</span>`));
  assert.match(html, /<span class="sr-only" role="status" aria-live="polite">Working…<\/span>/);
  const long = render({ running: true }, { elapsed: 57, outputTokens: 1100, waiting: 'model' });
  assert.ok(long.includes(CLOCK('57s')) && long.includes(`${TRAILING}1.1k tokens</span>`));
  assert.ok(render({ running: true }, { elapsed: 75, outputTokens: 5 }).includes(CLOCK('1m 15s')));
});

test('one token reads "1 token"; under 2 s there is no clock and no tokens', () => {
  assert.ok(render({ running: true }, { elapsed: 4, outputTokens: 1 }).includes(`${TRAILING}1 token</span>`));
  const early = render({ running: true }, { elapsed: 1, outputTokens: 50, waiting: 'model' });
  assert.match(early, /data-state="busy"/);
  assert.doesNotMatch(early, /tabular-nums">1s|tokens|select-none">·/);
  // No tokens reported: the clock alone.
  const clockOnly = render({ running: true }, { elapsed: 9 });
  assert.ok(clockOnly.includes(CLOCK('9s'))); assert.doesNotMatch(clockOnly, /tokens|select-none">·/);
});

test('waiting phases (sending, model, tools, responding) show no text label; the status announces Working…', () => {
  for (const [state, extra] of [[{ running: false, sending: true }, { elapsed: 5 }], [{ running: true }, { elapsed: 5, waiting: 'model' }],
    [{ running: true }, { elapsed: 5, waiting: 'tools' }], [{ running: true }, { elapsed: 5, waiting: null }]]) {
    const html = render(state, extra);
    assert.match(html, /data-state="busy"/);
    assert.ok(html.includes(CLOCK('5s')));
    assert.doesNotMatch(html, /Waiting for Claude|Running tools|Sending|Connecting/);
    assert.match(html, /role="status" aria-live="polite">Working…</);
  }
  assert.equal(Model.workingLineProps(view({ running: false, sending: true }), {}).waiting, 'sending');
});

test('thinking: with the flag served on, U6 shows no thinking text or chip (BSe only holds the row)', () => {
  for (const thinking of [{ kind: 'active', open: true }, { kind: 'active', open: false }, { kind: 'done', seconds: 4 }]) {
    const html = render({ running: true }, { elapsed: 5, outputTokens: 3, thinking });
    assert.ok(html.includes(`${TRAILING}3 tokens</span>`));
    assert.doesNotMatch(html, />Thinking<|Thinking…|Thought for/);
  }
  assert.deepEqual(Model.workingLineThinking({ kind: 'active' }, true), { kind: 'active', open: true });
  assert.deepEqual(Model.workingLineThinking({ kind: 'active' }, false), { kind: 'active', open: false });
  assert.deepEqual(Model.workingLineThinking({ kind: 'done', seconds: 3 }, false), { kind: 'done', seconds: 3 });
});

test('compacting, stopping and the blocked row name their state', () => {
  const compacting = render({ running: true }, { elapsed: 12, activity: { kind: 'compacting' } });
  assert.match(compacting, /data-cds="ShimmerText"[^>]*>Compacting session<\/span>/);
  assert.ok(compacting.includes(CLOCK('12s')));
  const stopping = render({ running: true, stopping: true }, { elapsed: 12 });
  assert.match(stopping, /data-turn-working="true"/); assert.match(stopping, />Stopping<\/span>/); assert.doesNotMatch(stopping, /tabular-nums">12s/);
  const blocked = render({ running: true, waiting: true }, {});
  assert.match(blocked, /data-turn-working="false"/); assert.match(blocked, /data-cds="TurnStatus" data-state="blocked"/);
  assert.match(blocked, /Needs your input/);
});

